package com.example.ayni.sync.controller;import com.example.ayni.sync.dto.SyncRequests;import com.example.ayni.sync.service.SyncService;import jakarta.validation.Valid;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/sync")public class SyncController{private final SyncService service;public SyncController(SyncService service){this.service=service;}@PostMapping public List<SyncRequests.Result> sync(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody SyncRequests.Batch batch){return service.sync(UUID.fromString(jwt.getSubject()),batch);}}
